ICONS["batch_rename"] = ICONS["edit_note"];
ICONS["view_grid"] = ICONS["grid_view"];
ICONS["view_list"] = ICONS["view_headline"];
ICONS["open_with"] = ICONS["open_in_new"];

export type IconName = keyof typeof ICONS | string;

export function Icon(props: { name: IconName; size?: number; className?: string; style?: React.CSSProperties; weight?: number }) {
  const { name, size = 24, className, style, weight } = props;
  const inner = ICONS[name] ?? ICONS.insert_drive_file;
  return (
    <svg
      className={className}
      style={{ width: size, height: size, display: "block", fontWeight: weight, ...style }}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: inner }}
    />
  );
}
